package com.ecommerce.inventory.domain.model;

import java.util.Objects;
import java.util.UUID;

/**
 * Identity of a reservation, generated by Inventory. It is the {@code aggregateId} and Kafka key of
 * every {@code inventory.*} event.
 *
 * @param value the reservation id
 */
public record ReservationId(UUID value) {

    /** Validates the reservation id. */
    public ReservationId {
        Objects.requireNonNull(value, "reservation id");
    }

    /**
     * Generates a new random reservation id.
     *
     * @return a new reservation id
     */
    public static ReservationId newId() {
        return new ReservationId(UUID.randomUUID());
    }

    @Override
    public String toString() {
        return value.toString();
    }
}
